def minimum_zigzag_decrements(nums):
 def cost(start):
  total=0
  for i in range(start,len(nums),2):total+=max(0,nums[i]-min(nums[i-1] if i else float('inf'),nums[i+1] if i+1<len(nums) else float('inf'))+1)
  return total
 return min(cost(0),cost(1))

